-- ============================================================
-- SEED EXT 5: Módulo 07 — Present Perfect (ex 185-260)
-- Consolidação avançada: PP em TOEFL essays completos, PP em
-- resenhas literárias, PP com all discourse markers avançados
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'present-perfect';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo present-perfect não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 51: PP em introduções de TOEFL essays
  (cid,51,185,'gap_fill','Inequality _____ (emerge) as one of the defining political issues of the twenty-first century, generating intense academic and policy debate.','has emerged',NULL,'PP for development from past to present: established present relevance.','easy'),
  (cid,51,186,'gap_fill','Digital technology _____ (fundamentally/transform) how people communicate, work, and access information, yet its implications for democratic governance _____ (not/fully/evaluate/passive).','has fundamentally transformed / have not been fully evaluated',NULL,'PP for past-to-present transformation + PP passive negative for gap.','medium'),
  (cid,51,187,'gap_fill','Despite decades of policy attention, urban poverty _____ (not/eliminate/passive) in any major metropolitan area, raising questions about the effectiveness of current approaches.','has not been eliminated',NULL,'PP passive negative for persistent failure to present.','medium'),
  (cid,51,188,'multiple_choice','Which PP sentence BEST opens a TOEFL essay introduction?','The relationship between economic growth and environmental sustainability has become one of the central tensions in contemporary development policy.','["The relationship was central in 2020.","The relationship is becoming central.","The relationship between economic growth and environmental sustainability has become one of the central tensions in contemporary development policy.","The relationship has been central in the 1990s."]','PP ''has become'' = process from past to current central status.','easy'),
  (cid,51,189,'gap_fill','Researchers _____ (document) a consistent positive relationship between educational attainment and civic engagement, though the direction of causality _____ (long/dispute/passive).','have documented / has long been disputed',NULL,'PP for accumulated evidence + PP passive for ongoing scholarly debate.','medium'),

  -- BLOCK 52: PP em discussões de resultados
  (cid,52,190,'gap_fill','This study _____ (contribute) to the literature by demonstrating that X _____ (associate/passive) with Y even after controlling for Z.','has contributed / is associated',NULL,'Discussion: PP for current contribution + PS passive for association (general finding).','hard'),
  (cid,52,191,'gap_fill','The findings _____ (add) to a growing body of evidence suggesting that current policy frameworks _____ (not/adequately/account for) the complexity of the problem.','have added / do not adequately account for',NULL,'Discussion: PP for adding to literature + PS negative for current inadequacy.','medium'),
  (cid,52,192,'multiple_choice','In a research paper discussion, which correctly combines past simple and present perfect?','This study found that social capital significantly moderated the relationship; this finding has important implications for community development policy.','["This study has found that social capital significantly moderated; this finding had important implications.","This study found that social capital significantly moderated the relationship; this finding has important implications for community development policy.","This study found that social capital has significantly moderated; this finding has important implications.","This study has found that social capital significantly moderated; this finding has important implications."]','PS ''found'' (specific study result) + PP ''has important implications'' (current relevance).','hard'),
  (cid,52,193,'gap_fill','Previous meta-analyses _____ (examine) interventions targeting depression, but none _____ (focus) specifically on the sub-population of healthcare workers.','have examined / has focused',NULL,'PP for existing body of work + PP negative for identified gap.','hard'),
  (cid,52,194,'gap_fill','The mechanism by which X influences Y _____ (not/yet/establish/passive), though several hypotheses _____ (advance/passive) in the recent literature.','has not yet been established / have been advanced',NULL,'PP passive negative + PP passive for proposed hypotheses.','hard'),

  -- BLOCK 53: PP em conclusões de TOEFL essays
  (cid,53,195,'production','[TOEFL Writing — 150 words] Write a TOEFL essay conclusion on climate change policy. Use PP for what has been argued/demonstrated, and PS/future for recommendations.','',NULL,'This essay has argued that addressing climate change requires a combination of market mechanisms, regulatory intervention, and public investment that no single policy instrument can achieve alone. The evidence examined has demonstrated that countries that have coordinated these tools coherently have made substantially more progress than those that have relied on market forces alone. The analysis has also shown that the distributional consequences of climate policy cannot be treated as secondary: measures that impose costs on lower-income populations without adequate compensation will fail to sustain political support over the decades-long timescale that the energy transition requires. Future policy design must therefore integrate both the technical requirements of decarbonization and the political economy of building and maintaining coalitions for change. The window for action remains open, but the evidence suggests it is narrowing more rapidly than policy timelines in most countries currently reflect.','hard'),
  (cid,53,196,'gap_fill','In conclusion, this essay _____ (argue) that the relationship between X and Y is conditioned by Z, and _____ (show) through three lines of evidence that current policy _____ (insufficiently/account for) this complexity.','has argued / has shown / insufficiently accounts for',NULL,'PP for essay''s accumulated argument (has argued/has shown) + PS for current policy inadequacy.','hard'),
  (cid,53,197,'gap_fill','The analysis _____ (reveal) that neither traditional theory nor current institutional arrangements _____ (adequate/prove/passive) to address the challenge, and _____ (suggest) that fundamental redesign is required.','has revealed / have proved / has suggested',NULL,'PP triple sequence in academic conclusion: revealed, have proved, has suggested.','hard'),

  -- BLOCK 54: PP com adverbiais avançados
  (cid,54,198,'gap_fill','Interest in renewable energy _____ (surge) over the past decade, _____ (drive) by falling costs, policy incentives, and increasing public concern about climate change.','has surged / driven',NULL,'PP + participial result/cause clause.','medium'),
  (cid,54,199,'gap_fill','The technology _____ (improve) dramatically since it _____ (introduce/passive) commercially in 2012, and costs _____ (fall) by more than 80%.','has improved / was introduced / have fallen',NULL,'PP (has improved) + PS passive (was introduced, specific year) + PP (have fallen).','hard'),
  (cid,54,200,'multiple_choice','Which PP construction correctly uses ''since'' and ''for''?','''Researchers have studied this phenomenon since the 1970s and have published over 500 papers on it in the past five years.''','["Researchers have studied this since 1970 and published 500 papers for the past five years.","Researchers studied this since the 1970s and have published over 500 papers for five years.","Researchers have studied this phenomenon since the 1970s and have published over 500 papers on it in the past five years.","Researchers are studying this since the 1970s and have published over 500 papers in five years."]','PP + since (from past point) + PP + in the past five years (recent period).','hard'),
  (cid,54,201,'gap_fill','No consensus _____ (emerge) on this question despite decades of research, and the debate _____ (if anything/intensify) in recent years.','has emerged / has if anything intensified',NULL,'PP negative + PP with ''if anything'' (emphatic unexpected direction).','hard'),

  -- BLOCK 55: TOEFL Reading avançado
  (cid,55,202,'multiple_choice','[TOEFL Reading] ''The prevalence of antibiotic-resistant bacteria has increased sharply over the past three decades, posing a growing threat to global health.'' The PP ''has increased'' connects this problem to:','The present moment — the increase is still ongoing and the threat is current.','["A completed historical problem with no present relevance","The present moment — the increase is still ongoing and the threat is current.","A specific event in a single year","A projected future problem"]','PP = past-to-present trend still relevant and ongoing.','easy'),
  (cid,55,203,'gap_fill','[TOEFL Reading] ''Technology _____ (disrupt) traditional media business models, and advertising revenues _____ (decline) sharply.'' Best forms for an academic paragraph about current media challenges?','has disrupted / have declined',NULL,'PP for disruption that began in the past and continues now.','easy'),
  (cid,55,204,'multiple_choice','[TOEFL Reading] ''Urban greenery has been shown to reduce heat island effects, lower air pollution, and improve mental health outcomes.'' This triple PP passive indicates:','Multiple research findings that are currently accepted as established knowledge.','["One study proved all three findings","Multiple research findings that are currently accepted as established knowledge.","Future projections","Historical data with no current relevance"]','PP passive ''has been shown'' = cumulative evidence with current authority.','easy'),
  (cid,55,205,'gap_fill','[TOEFL Reading] ''Migration _____ (always/shape) human civilization, but its contemporary scale and pace _____ (introduce) challenges that historical migrations _____ (not/pose).'' Best forms?','has always shaped / have introduced / did not pose',NULL,'PP ''has always shaped'' (universal truth PP) + PP (introduced to present) + PS negative (historical contrast).','hard'),

  -- BLOCK 56: TOEFL Speaking avançado
  (cid,56,206,'production','[TOEFL Speaking — 45s] A reading discusses advances in renewable energy. A lecture argues that grid infrastructure has not kept up. Summarize both using PP.','',NULL,'The reading celebrates the dramatic progress that renewable energy technology has made over the past decade. Solar and wind costs have fallen by more than 90% and 70% respectively, and installed capacity has grown faster than most forecasts predicted. However, the lecture introduces a significant caveat: grid infrastructure has not kept pace with the growth in renewable generation capacity. The professor argues that transmission networks have been designed for a centralized generation system and have not been adequately upgraded to handle the distributed, variable output that solar and wind produce. As a result, curtailment — the practice of switching off renewable generators when the grid cannot absorb their output — has increased significantly. The professor concludes that the bottleneck has shifted from generation technology to grid infrastructure, and that the investment in transmission and storage that has not yet been made may determine the pace of decarbonization more than any further improvements in renewable generation technology.','hard'),
  (cid,56,207,'production','[TOEFL Speaking — 45s] Discuss changes in public health over the past century. Use PP for cumulative progress and PS for specific historical events.','',NULL,'The past century has witnessed some of the most dramatic improvements in human health outcomes ever recorded. Life expectancy has nearly doubled in most countries since 1900, driven by dramatic reductions in infant and child mortality from infectious diseases. The development of vaccines against polio, smallpox, measles, and dozens of other killers has eliminated or substantially reduced diseases that once caused mass mortality. Sanitation infrastructure has been extended to a far larger share of the global population, dramatically reducing waterborne disease. Antibiotics, introduced into clinical practice in the 1940s, transformed the management of bacterial infections. At the same time, the disease burden has shifted: as infectious disease mortality has fallen, chronic non-communicable diseases — cardiovascular disease, cancer, diabetes — have become the dominant causes of death in high-income countries, and this pattern is rapidly emerging in middle-income countries as well.','hard'),

  -- BLOCK 57: TOEFL Writing avançado
  (cid,57,208,'production','[TOEFL Writing — 200 words] Write a body paragraph on the history of women''s economic participation. Use PP for long-term trends, PS for historical events, and PC for current processes.','',NULL,'Women''s participation in the formal economy has expanded dramatically over the past century, though significant barriers and inequalities persist. At the start of the twentieth century, women in most countries were legally barred from many professions, lacked the right to own property independently, and were expected to withdraw from paid employment upon marriage. These restrictions have been progressively dismantled: in most high-income countries, formal legal barriers to women''s employment have been eliminated, and gender gaps in educational attainment have been reversed — women now outnumber men in higher education enrollment in most wealthy nations. Nevertheless, earnings gaps between men and women have persisted even among workers with comparable education and experience, a disparity that researchers attribute to a combination of occupational segregation, the undervaluation of work in feminized sectors, and the unequal distribution of caregiving responsibilities that still disadvantages women in competitive labor markets. Progress has been made, but it has been uneven and incomplete: women have made the greatest gains in professional and managerial roles in high-income countries, while women in low-income countries and informal employment continue to face conditions that combine precarity with the full burden of domestic care work.','hard'),
  (cid,57,209,'production','[TOEFL Writing — 200 words] Write a body paragraph on digital platforms and market concentration. Use PP for current state of industry, and PS for key historical developments.','',NULL,'Digital platform markets have concentrated dramatically since the early 2000s, producing dominant firms with market positions that appear difficult to challenge through conventional competition. Google achieved dominance in search advertising in the early 2000s, Facebook established its social networking monopoly through the network effects that drove rivals from the market during the following decade, and Amazon has built an e-commerce and cloud infrastructure that competitors have found difficult to replicate. These companies have also grown through acquisition: Facebook purchased Instagram in 2012 and WhatsApp in 2014 when both were potential rivals; Google has made hundreds of acquisitions that have extended its reach into adjacent markets. Regulators have struggled to respond: antitrust law developed in the industrial era was not designed to address markets where the dominant firm''s product is free at point of use and where concentration reflects not collusion but the structural dynamics of platforms. The EU''s Digital Markets Act, adopted in 2022, represents the most serious attempt yet to regulate gatekeeper platforms, but whether it will substantially alter competitive dynamics remains to be seen. The data advantages that dominant platforms have accumulated over years of user interaction have created durable moats that new market instruments must specifically target.','hard'),

  -- BLOCK 58: Final exercícios
  (cid,58,210,'production','[TOEFL Writing — 200 words] Write a paragraph on global poverty reduction. Use PP for cumulative progress, PS for specific events, and correct hedging.','',NULL,'Global poverty reduction has been one of the most significant achievements of the late twentieth and early twenty-first centuries. Between 1990 and 2019, the share of the world''s population living in extreme poverty — defined by the World Bank as living on less than $1.90 per day — fell from approximately 36% to under 10%, representing the largest and fastest reduction in absolute poverty in human history. This progress was driven primarily by economic growth in East and South Asia, particularly the rapid industrialization of China and India, which lifted hundreds of millions of people out of poverty in the course of two to three generations. Sub-Saharan Africa has made slower progress, and by some measures the absolute number of extremely poor people in the region has increased even as the rate has declined, reflecting rapid population growth alongside modest per capita income gains. The COVID-19 pandemic reversed several years of poverty reduction in 2020 and 2021, with the first year-on-year increase in extreme poverty in a generation occurring in 2020. The long-term trend of poverty reduction has resumed since 2022, but the pace has slowed, and reaching the Sustainable Development Goal of ending extreme poverty by 2030 now appears unlikely under current trajectories.','hard'),
  (cid,58,211,'production','[TOEFL Speaking — 60s] Discuss how international law has developed since World War II. Use PP for cumulative development, PS for key founding moments.','',NULL,'The body of international law has expanded dramatically since the end of the Second World War, growing from a relatively thin set of rules governing state relations into a complex architecture that touches on human rights, environmental protection, trade, intellectual property, criminal accountability, and the laws of armed conflict. The founding of the United Nations in 1945 established the prohibition on the use of force against the territorial integrity of other states as a cornerstone of international order. The Universal Declaration of Human Rights was adopted in 1948 and provided the foundation for subsequent binding treaties that have elaborated human rights obligations in considerable detail. International criminal law has developed through the establishment of ad hoc tribunals — for the former Yugoslavia in 1993 and Rwanda in 1994 — and then through the creation of the International Criminal Court in 2002, which has asserted jurisdiction over genocide, crimes against humanity, and war crimes. International environmental law has developed through a succession of multilateral agreements including the Vienna Convention on ozone depletion, the Convention on Biological Diversity, and the Paris Agreement on climate change. Despite this growth, significant enforcement gaps remain: powerful states have frequently acted in ways that violate the frameworks they have formally endorsed, and the international legal system lacks the coercive mechanisms of domestic legal orders.','hard'),
  (cid,58,212,'production','[TOEFL Writing — Final 200 words] Write a body paragraph on higher education access using PP, PS, and present simple with precision.','',NULL,'Access to higher education has expanded dramatically over the past half century, but significant inequalities in who benefits from this expansion have persisted throughout. In 1960, fewer than 5% of the world''s working-age population had completed a tertiary qualification; by 2020, this figure had risen to approximately 40% in high-income countries. This expansion reflects both demographic changes and deliberate policy decisions: governments in many countries have extended public funding for universities, established student loan schemes, and created new institutions designed to reach non-traditional student populations. However, completion rates and graduate outcomes vary enormously by socioeconomic background. First-generation college students — those whose parents did not attend university — have been found to face significantly higher dropout rates and lower earnings premiums than students from more privileged backgrounds, even when they attend the same institutions. This suggests that the formal expansion of access has not been accompanied by an equivalent democratization of outcomes. Research further demonstrates that prestige hierarchies within higher education systems are strongly self-reproducing: students from high-income families consistently gain admission to the most selective institutions at rates that far exceed their academic ability relative to less affluent peers, reflecting a combination of better secondary schooling, application coaching, and institutional preferences that favor the socially advantaged.','hard'),
  (cid,58,213,'production','[TOEFL Speaking — 60s] What global progress has been made in addressing infectious diseases? What challenges remain? Use PP throughout.','',NULL,'Global health has made extraordinary progress against infectious disease over the past century, driven by the development and deployment of vaccines, antibiotics, and improved sanitation infrastructure. Smallpox has been eradicated entirely — the only infectious disease to have been eliminated through deliberate human intervention. Polio has been eliminated from all but a small number of countries, and cases have fallen by more than 99% from the peak in the 1980s. HIV/AIDS, which killed millions in the 1980s and 1990s before effective antiretroviral treatments became available, has been transformed from a death sentence into a manageable chronic condition for the millions who have gained access to treatment. Childhood mortality from measles, diarrheal diseases, and respiratory infections has fallen dramatically, even if elimination has not yet been achieved. Despite this progress, significant challenges remain. Antibiotic resistance has emerged as one of the most serious threats to global health, with drug-resistant strains of tuberculosis, gonorrhea, and other pathogens spreading at a rate that existing treatment pipelines have not kept pace with. The COVID-19 pandemic demonstrated that the world remains highly vulnerable to novel infectious diseases, and that the international systems for detection, sharing, and response have not developed to a level commensurate with the risk. Pandemic preparedness has improved, but not yet sufficiently.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
